def count_length_three_palindromes(s):
    first = [-1] * 26
    last = [-1] * 26
    for index, char in enumerate(s):
        code = ord(char) - 97
        if first[code] == -1:
            first[code] = index
        last[code] = index
    answer = 0
    for code in range(26):
        if first[code] < last[code]:
            answer += len(set(s[first[code] + 1:last[code]]))
    return answer

